//! Adjoints of the per-cell material updates generated by Rust's
//! Enzyme-based automatic differentiation (`std::autodiff`), and their
//! comparison with the hand-written adjoints of [`super::cell`].
//!
//! Only built with the `enzyme` cargo feature, which needs a nightly
//! toolchain with the `enzyme-preview` rustup component, `-Zautodiff=Enable`
//! and fat LTO (`scripts/test_enzyme.sh`). The pinned stable toolchain
//! cannot build it (no Enzyme component is published for it), and
//! cuda-oxide's codegen backend rejects the `autodiff` intrinsic, so the
//! generated adjoints cannot become GPU kernels.
//!
//! On the CPU the generated adjoints are used as a check, not in the
//! engine: with the nightly this was developed on (1.102.0-nightly,
//! 2026-11-20) rustc aborts inside Enzyme's type analysis (`illegal
//! insertion`, `Enzyme/TypeAnalysis/TypeTree.h:364`) as soon as the reverse
//! engine is alive in the same LTO unit, i.e. when lightsim-core is built
//! as a dependency (integration tests, the Python extension) or when a unit
//! test instantiates the engine, even if the engine does not call the
//! generated functions. The crate's own unit-test binary, where the engine
//! is dead code, builds and passes. The reverse pass therefore uses the
//! hand-written adjoints, which these tests show to agree with Enzyme's to
//! single precision.

use super::cell;
use std::autodiff::autodiff_reverse;

/// The chi2/chi3 cell step `E(n+1) = F(E(n), E_lin; a, b)` (four Newton
/// iterations, exactly the engine's `nl_solve`).
#[autodiff_reverse(d_nl_step, Active, Active, Active, Active, Active)]
#[inline(never)]
pub fn nl_step(e: f32, elin: f32, a: f32, b: f32) -> f32 {
    let d = elin - e;
    let mut u = d / (1.0 + 2.0 * a * e + 3.0 * b * e * e);
    for _ in 0..4 {
        let f = u + a * (2.0 * e * u + u * u) + b * (3.0 * e * e * u + 3.0 * e * u * u + u * u * u) - d;
        let fp = 1.0 + a * (2.0 * e + 2.0 * u) + b * (3.0 * e * e + 6.0 * e * u + 3.0 * u * u);
        u -= f / fp;
    }
    e + u
}

/// `[dF/de, dF/delin, dF/da, dF/db]` of [`nl_step`] by reverse-mode AD
/// through the Newton iterations.
pub fn nl_step_grad(e: f32, elin: f32, a: f32, b: f32) -> [f32; 4] {
    let (_, de, dl, da, db) = d_nl_step(e, elin, a, b, 1.0);
    [de, dl, da, db]
}

/// One step of a two-pole dispersive cell, `out[0]` weighted by `g` and
/// summed: Enzyme differentiates the scalar `<g, step(x)>` with respect to
/// `x`, i.e. computes the vector-Jacobian product.
#[cfg(test)]
#[autodiff_reverse(d_disp_dot, Duplicated, Const, Const, Const, Active)]
#[inline(never)]
pub fn disp_dot(x: &[f32; 6], c: &[f32; 6], scale: f32, g: &[f32; 5]) -> f32 {
    let mut out = [0f32; 5];
    cell::disp_step2(x, c, scale, &mut out);
    let mut s = 0.0;
    for i in 0..5 {
        s += g[i] * out[i];
    }
    s
}

/// Vector-Jacobian product of [`cell::disp_step2`] generated by Enzyme.
#[cfg(test)]
pub fn disp_step2_vjp(x: &[f32; 6], c: &[f32; 6], scale: f32, g: &[f32; 5]) -> [f32; 6] {
    let mut dx = [0f32; 6];
    let _ = d_disp_dot(x, &mut dx, c, scale, g, 1.0);
    dx
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn enzyme_nonlinear_step_matches_hand_written_adjoint() {
        let mut worst = 0f32;
        for &(e, elin, a, b) in &[(0.3f32, 0.42f32, 0.2f32, 0.5f32), (-0.7, -0.55, 0.1, 0.3), (0.05, 0.4, -0.2, 0.8), (1.1, 0.9, 0.0, 0.25), (0.6, 0.61, 0.3, 0.0)] {
            let e1 = cell::nl_step(e, elin, a, b);
            assert_eq!(e1, nl_step(e, elin, a, b));
            let ad = nl_step_grad(e, elin, a, b);
            let (fe, fl) = cell::nl_partials(e, e1, a, b);
            let (fa, fb) = cell::nl_partials_coef(e, e1, a, b);
            for (x, y) in ad.iter().zip([fe, fl, fa, fb]) {
                worst = worst.max((x - y).abs() / y.abs().max(1.0));
            }
        }
        println!("enzyme vs implicit-function adjoint of the chi2/chi3 step: max rel. difference {worst:.2e}");
        assert!(worst < 2e-5, "{worst}");
    }

    #[test]
    fn enzyme_dispersive_cell_matches_hand_written_adjoint() {
        let c = [1.93f32, -0.96, 0.031, 1.7, -0.8, 0.05];
        let x = [0.3f32, 0.5, -0.2, 0.1, 0.7, -0.4];
        let mut worst = 0f32;
        for o in 0..5 {
            let mut g = [0.25f32; 5];
            g[o] = 1.0;
            let ad = disp_step2_vjp(&x, &c, 0.4, &g);
            let hand = cell::disp_step2_vjp(&c, 0.4, &g);
            for i in 0..6 {
                worst = worst.max((ad[i] - hand[i]).abs());
            }
        }
        println!("enzyme vs hand-written adjoint of the two-pole cell: max difference {worst:.2e}");
        assert!(worst < 1e-6, "{worst}");
    }
}
